func:
/**
 * Builds a plain HTTP GET request for a signed Rayvn URL.
 * No authentication required — signed URLs are publicly accessible.
 * Mirrors Get Wasos file — Build download request.
 */
const file = msg.payload;

return {
    _msgid:     msg._msgid,
    _dl:        msg._dl,
    parts:      msg.parts,
    metadata:   msg.metadata,
    _file_meta: {
        url:  file.url,
        name: file.name || "attachment",
        type: file.type || "application/octet-stream",
        size: file.size || 0
    },
    url:   file.url,
    topic: msg.topic
};
